def _runs(indices):
    """Return half-open contiguous runs of indices."""
    if not indices:
        return []
    result = []
    start = prev = indices[0]
    for value in indices[1:]:
        if value != prev + 1:
            result.append((start, prev + 1))
            start = value
        prev = value
    result.append((start, prev + 1))
    return result


def _modal_center(runs):
    lengths = Counter(end - start for start, end in runs)
    # Prefer the larger run on a tie, so a clipped final tile does not shift centers.
    width = max(lengths, key=lambda n: (lengths[n], n))
    offset = width // 2
    return [start + offset for start, _ in runs]


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h or not w:
        return out

    row_runs = _runs([r for r in range(h) if any(grid[r])])
    col_runs = _runs([c for c in range(w) if any(grid[r][c] for r in range(h))])
    row_centers = [r for r in _modal_center(row_runs) if r < h]
    col_centers = [c for c in _modal_center(col_runs) if c < w]
    centers = [(r, c, grid[r][c]) for r in row_centers for c in col_centers if grid[r][c] != 0]
    if not centers:
        return out

    # The most common tile-center color is the unmarked/background class.
    background = Counter(color for _, _, color in centers).most_common(1)[0][0]

    # Match marked colors along each tile row; paint only the empty corridors,
    # leaving intervening tiles and their borders untouched.
    for r in row_centers:
        by_color = {}
        for c in col_centers:
            color = grid[r][c]
            if color and color != background:
                by_color.setdefault(color, []).append(c)
        for color, positions in by_color.items():
            if len(positions) > 1:
                for c in range(min(positions), max(positions) + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color

    # And likewise along each tile column.
    for c in col_centers:
