            color = grid[r][c]
            if color and color != background:
                by_color.setdefault(color, []).append(r)
        for color, positions in by_color.items():
            if len(positions) > 1:
                for r in range(min(positions), max(positions) + 1):
                    if grid[r][c] == 0:
                        out[r][c] = color
    return out


